<?php namespace App\Controllers;
class DailyEntries extends BaseController{
 public function index(){if($r=$this->mustLogin())return $r;$month=$this->request->getGet('month')?:date('Y-m');$mat=$this->request->getGet('material_id');$db=db_connect();$materials=$db->table('materials')->orderBy('id')->get()->getResultArray();$sql="SELECT d.*,m.code,m.description,u.name user_name FROM daily_entries d JOIN materials m ON m.id=d.material_id JOIN users u ON u.id=d.created_by WHERE d.month_key=?";$args=[$month];if($mat){$sql.=" AND d.material_id=?";$args[]=$mat;}$sql.=" ORDER BY d.entry_date DESC,d.id DESC";return $this->render('daily_entries/index',['pageTitle'=>'Daily Entries','month'=>$month,'materials'=>$materials,'rows'=>$db->query($sql,$args)->getResultArray()]);}
 public function save(){if($r=$this->mustLogin())return $r;$p=$this->request->getPost();$date=$p['entry_date'];$p['month_key']=substr($date,0,7);$p['created_by']=session()->get('user')['id'];$p['updated_by']=session()->get('user')['id'];$model=new \App\Models\DailyEntryModel();$old=$model->where(['material_id'=>$p['material_id'],'entry_date'=>$date])->first();if($old){if(session()->get('user')['role']!=='admin'&&$old['created_by']!=session()->get('user')['id'])return redirect()->back()->with('error','Access denied.');$model->update($old['id'],$p);$id=$old['id'];}else{$id=$model->insert($p);} (new \App\Models\ActivityLogModel())->insert(['user_id'=>session()->get('user')['id'],'action'=>$old?'UPDATE':'CREATE','entity_type'=>'daily_entry','entity_id'=>$id,'details'=>'Daily entry for material '.$p['material_id'].' on '.$date]);return redirect()->back()->with('success','Daily entry saved.');}
 public function delete($id){if($r=$this->mustLogin())return $r;$m=new \App\Models\DailyEntryModel();$row=$m->find($id);if(!$row)return redirect()->back();if(session()->get('user')['role']!=='admin'&&$row['created_by']!=session()->get('user')['id'])return redirect()->back()->with('error','Access denied.');$m->delete($id);return redirect()->back()->with('success','Entry deleted.');}}
